package com.armsx2.ui.manual

/** Offline, read-only help. No account data, game files or settings are read by this catalogue. */
internal data class ManualTopic(val title: String, val body: String)
internal data class ManualChapter(val id: String, val title: String, val summary: String, val topics: List<ManualTopic>)
internal data class ManualMatch(val chapter: ManualChapter, val topic: ManualTopic)

private fun topic(title: String, body: String) = ManualTopic(title, body)
private fun chapter(id: String, title: String, summary: String, vararg topics: ManualTopic) =
    ManualChapter(id, title, summary, topics.toList())

internal val MANUAL_CHAPTERS = listOf(
    chapter("start", "Getting started", "First launch, navigation and your first game",
        topic("Set up ARMSX1", "Open the sidebar → Setup / Change Folders. Choose your game folders and a PlayStation BIOS you legally obtained. Allow Android access to each selected folder. Return to the library and refresh, then select a game cover to play. ARMSX1 emulates PlayStation (PS1), not PS2, PSP or PS3."),
        topic("Open the sidebar and quick menu", "Use the menu button in the library to open the sidebar. During a game, use the pause button, Android Back (when enabled in Shortcuts), or your assigned Menu / Pause hotkey. Resume returns to the game; Close ends the session. Exit closes the app. Save before restarting, closing or updating."),
        topic("Use a controller or touchscreen", "Touch a row to open it. With a controller, use the D-pad or stick to move the highlight and the configured confirm/cancel buttons to select or return. In Settings, left/right adjusts many values and L1/R1 changes tabs. In text entry, use the built-in keyboard; Done keeps the text. The system keyboard can be enabled in App settings."),
        topic("Find a setting", "Open Settings and use its search button to find a control by name. Search results switch to its tab and highlight the row. Read the short description beside the setting for what it does. This manual explains the workflow and related settings; search here for terms such as memory card, shader, BIOS or rotation."),
        topic("Rearrange settings tabs", "Hold and drag a settings tab to change its position. With a controller, highlight a tab and press Y to move it; left/right changes its position, A or Y saves, and B cancels. Moving tabs changes their order, not their settings."),
    ),
    chapter("library", "Game library", "Scanning, views, covers, collections and multi-disc games",
        topic("Add, refresh and remove game folders", "Use Setup / Change Folders or Settings → Library to add a ROM directory. Enable subfolder scanning for folders containing nested games. Refresh after copying or renaming files. Removing a library folder stops displaying its games; it is not a command to delete the ROMs. Android access must remain granted."),
        topic("Search and change views", "Use the library search field to narrow the list as you type. The view controls switch between list, grid and shelf layouts. App settings control cover size, tile opacity, game names, the search field and Recently Played. Clearing recents removes history, not games or saves."),
        topic("Collections, favourites and hidden games", "Use a game's context menu (hold its cover) to see the available library actions, including organisation and per-game settings. Collections group existing library entries rather than copying ROMs. Check the hidden-games filter if a scanned title disappears. Collection and favourite controls organise the library without changing the disc image."),
        topic("Game details, names and covers", "Open a game's settings → Info to see its identified title, disc serial, region, format and path. Use custom name or cover controls to replace the displayed metadata. A custom name does not change the game's region or cheat ID. Online cover retrieval needs a connection and a matching entry; a custom image is the fallback for an unmatched game."),
        topic("2D covers and 3D cases", "Choose the artwork/view option you prefer in the library controls. Different cover styles can require different downloaded artwork. Refresh after updating the library; if only one game remains wrong, set a custom cover in its Info page. Clearing caches can require images to be downloaded again."),
        topic("M3U playlists", "Keep all discs and a plain-text .m3u playlist together. Put one disc filename or relative path on each line, in order. Launch the playlist rather than an individual disc so Swap Disc knows the set. Referenced discs are hidden from the normal library when the playlist is detected; the files remain on storage."),
        topic("PBP and swapping discs", "A multi-disc PBP contains more than one image in a single file. Launch it, then use Quick menu → Swap Disc to select an embedded disc. For M3U games, choose a listed disc. A standalone single-disc image may instead need the file picker. Swap when the game requests it; use the Swap Disc shortcut if you assigned one. Do not restart or Swap Game when the game is asking for another disc."),
        topic("Launching from another frontend", "Configure your frontend to launch ARMSX1 with the game's path or Android document URI. In Shortcuts, enable return to the external launcher if Close / Exit should return there. Opening a game from ARMSX1's own library normally returns to its library. An external launcher must also supply a file ARMSX1 has permission to read."),
    ),
    chapter("files", "User data, BIOS and game files", "Storage permissions, backups, CUE/BIN and SBI",
        topic("Choose the user-data folder", "Open Sidebar → Setup / Change Folders and use the user/system-data directory control. Choose a writable folder in Android's picker and grant access. Keep ROM folders separate if you want a tidy backup. Changing a location is not the same as migrating every old file: follow the migration/import options actually offered and verify existing saves before deleting the old folder."),
        topic("Back up before moving data", "Close the game so memory-card writes finish. Export memory cards and any save states you need, and use App settings' backup/export tools for the data they list. Keep the original files until the new location has been tested. Android app-private data may be removed on uninstall; an APK update with the same package and signing key normally preserves it."),
        topic("Import and select BIOS", "Use BIOS Location in the sidebar or the BIOS tab. Import a BIOS file or scan the folder containing your dumps. Auto selection chooses from recognised PlayStation BIOS files. A forced BIOS overrides automatic selection; Clear forced BIOS restores it. The preferred console model helps select among available files. No BIOS is supplied by this manual."),
        topic("Boot BIOS versus skip BIOS", "Sidebar → Boot BIOS runs the console without a disc, useful for checking BIOS and memory cards. Settings → Emulation → Skip BIOS controls whether a game uses fast boot or shows the startup sequence. A missing or incompatible BIOS is not repaired by enabling fast boot. Some BIOS changes need a fresh game launch."),
        topic("CUE and BIN access", "A CUE is a text descriptor, not the game data. Keep every referenced BIN/audio track in the expected relative location and preserve filenames. Grant access to the containing directory, not just an isolated CUE. Refresh the library after moving the set. If the CUE cannot be opened, verify its track paths and Android folder permission."),
        topic("SBI files and protected PAL games", "Some PAL releases need subchannel correction data. Use an SBI matching the exact disc/region/revision, alongside the corresponding image with the matching base name when possible. Seeing an SBI detected does not prove it is the correct one. Keep it with the game through moves/imports. A different region's SBI or a missing track cannot be fixed by changing rendering settings."),
    ),
    chapter("scope", "Global and per-game settings", "Overrides, automatic saving and reset",
        topic("Apply to one game or all games", "Sidebar → Settings opens global settings. Hold a game cover and open its settings to edit that game. Where available, the Global / This game control changes the scope. A per-game override wins over the global value; untouched controls continue following global settings. Check the scope before changing graphics, BIOS, audio or controls."),
        topic("Save changes and restart", "Normal settings save as you change them; there is no general Apply button. Display/pacing controls can apply live, while renderer, driver and boot options often require closing and relaunching the game. Follow the row's restart note. A running game may retain startup settings until its next launch."),
        topic("Restore inherited values", "Use the per-game override controls to return a setting to Global rather than manually copying today's global value. Otherwise it remains pinned and will not follow future global changes. OSD has its own Inherit / Use global option for the same reason."),
        topic("Reset and configuration import/export", "Reset applies to the tab/scope named in its confirmation, not automatically to every game or all app data. Use the Info page's per-game configuration export/import for the selected game, and App backup tools for broader backups. Export before experimenting. Restoring settings does not convert memory cards or make incompatible save states work."),
    ),
    chapter("video", "Video and rendering", "HD resolution, renderers, PGXP and image accuracy",
        topic("HD preset and internal resolution", "Open Video → HD rendering preset. Native is the original rendering scale; HD 2×, 3× or 4× selects the internal scale and enables hardware rasterisation as needed. The internal-resolution control is a finer adjustment of the same rendering scale, not a second HD multiplier. Higher scales sharpen 3D edges but cost GPU time; they do not redraw low-resolution art or movies. Restart the game after a change."),
        topic("Graphics backend and hardware rasterizer", "Choose Vulkan, system OpenGL ES or ANGLE in Video, then relaunch. ANGLE translates OpenGL ES through Vulkan; it is not a texture-enhancement option. The Hardware rasterizer switch controls how the core draws the scene and is separate from the frontend's backend choice. Turning hardware rasterisation off selects CPU software rendering and disables hardware-only effects. Confirm the actual running renderer in the quick menu/OSD rather than relying on the requested label."),
        topic("Custom Vulkan and OpenGL drivers", "Select Vulkan to show its driver manager; download or import a supported driver ZIP, then select it and restart. Use the system driver as the baseline. Custom drivers depend on the phone GPU and Android version. OpenGL/ANGLE has a separate implementation/driver selector. Do not assume a driver working on another device is compatible with yours."),
        topic("PGXP geometry precision", "Enable PGXP in Video to reduce polygon wobble and texture warping. It enables the hardware path. Compare a familiar scene before and after; if a game develops seams or incorrect geometry, disable it for that game and relaunch. It changes geometry accuracy, not the resolution of the original texture files."),
        topic("GPU mask bit and authentic dithering", "These are image-accuracy controls. Keep their normal defaults when diagnosing a game. Mask-bit handling matters for games that use drawing masks; changing it can break compositing. Dithering affects colour patterns/banding and is different from texture filtering. Change one setting at a time so you can identify the effect."),
        topic("Texture filtering and bilinear output", "Texture filtering changes the appearance of textures in the hardware renderer. Nearest preserves hard texel edges; Bilinear smooths them; xBR-style uses an edge-aware filter. Bilinear output scales the finished frame and is a separate control. Compare UI text and 3D surfaces: smoothing the final image is not the same as rendering the geometry at HD resolution."),
        topic("Downsampling", "Enable hardware rendering and a higher internal scale first. Downsampling reduces that rendered image before display, trading some visible sharpness for cleaner edges. It still pays the higher internal-resolution cost. Use a compatible factor; switch it off when judging whether an HD preset raises visible detail. HD presets disable downsampling."),
        topic("Deinterlacing", "Use Auto for the normal core behaviour. Force progressive can reduce interlacing effects in some 480-line content but can alter games designed around fields. Test it per game. Deinterlacing is not an overscan crop or a fix for missing game files."),
        topic("Widescreen hack", "For wider 3D geometry, enable Widescreen hack and choose a matching widescreen display ratio. Stretch alone only widens the finished image. Menus, 2D backgrounds and HUDs may stretch or show edge problems with the hack; disable it per game if necessary."),
        topic("Line detection and unavailable controls", "A row marked unavailable or read-only is not an enhancement you can enable in this core. Line-detection compatibility information is shown for the retired engine's setting; it is not a working SwanStation feature. Use the current controls rather than trying to restore old engine flags from a configuration file."),
    ),
    chapter("display", "Screen layout and orientation", "Portrait UI, landscape gameplay, sizing and overscan",
        topic("Library orientation and gameplay orientation", "App → Launcher orientation controls the frontend. Video → Gameplay orientation controls a running game independently. Choose Portrait for the library and Landscape for gameplay if that is your preference, including when the phone's normal auto-rotation is locked. Device/Auto modes follow the device policy; an explicit game orientation requests the chosen layout."),
        topic("Rotation versus orientation", "Gameplay orientation rotates the Android screen layout. Display rotation (0°, 90°, 180°, 270°) rotates the game's image inside it. Use image rotation for a sideways game, not as a substitute for the gameplay-orientation option. Check both values if the picture is sideways on a handheld."),
        topic("Aspect ratio and custom ratio", "Choose classic 4:3 for the normal shape, square pixels for that presentation, or widescreen/custom as desired. Custom exposes a ratio adjustment and presets. Stretch fills the available area and can distort shapes. Changing the aspect ratio does not reveal extra 3D scenery unless the game's camera or widescreen hack does that too."),
        topic("Integer scaling and overscan crop", "Integer scaling uses whole-number display steps and may leave larger borders. Overscan None keeps the full configured image; Small/Full trims edges and makes the remaining image appear larger. Do not crop away an important HUD just to fill the screen. Compare BIOS logos and a game scene separately; games use different video modes."),
        topic("Output scale, screen resolution and wide output", "Internal resolution changes the emulated rendering detail. Output-scale/screen-resolution controls affect the presentation surface or display mode instead. Widescreen-output resolution applies to its relevant output path. A bigger output surface cannot invent detail absent from a native-resolution render. Options that the device/core cannot apply should not be treated as guaranteed performance changes."),
        topic("Device performance controls", "Sustained performance requests steadier thermal behaviour; ADPF supplies Android performance hints; affinity restricts where emulation work runs. Their effect depends on the device. Low-latency and vertical-sync controls affect presentation/pacing rather than original game textures. Start with defaults, test one change, and watch speed and frame-time readings rather than only FPS."),
    ),
    chapter("shaders", "Shaders", "Download, apply, adjust and remove post-processing",
        topic("Install a shader pack", "Open Video or Quick menu → Display → Shader Packs. Use Download to install an available pack. After installation, its supported presets appear in Shader Preset. Installed files work offline; downloads need internet and writable storage."),
        topic("Enable and select a preset", "Turn on RetroArch Shaders and select a non-None preset. Choose an obvious CRT/scanline effect first to confirm it is applying, then select your preferred look. The shader processes the rendered image; its source resolution follows internal resolution. Unsupported presets fall back to the unfiltered image rather than proving that all presets are supported."),
        topic("Shader parameters and saved presets", "Open the selected preset's parameter controls. Adjust a parameter, compare the image and use reset to return a value to its default. In the parameter editor, D-pad up/down selects, left/right adjusts, A resets and B closes. Save a named preset when offered to reuse your adjustments. Importing a preset also requires its referenced shader/assets to be available."),
        topic("Turn shaders off or delete a pack", "Switch RetroArch Shaders off or select None for an unfiltered comparison. Delete in Shader Packs removes the installed pack, so a preset referencing it will no longer be available. Shaders add GPU work; if speed falls, try a simpler preset or disable the chain before reducing emulation accuracy."),
    ),
    chapter("textures", "Texture packs", "Automatic downloads, compatibility and making replacements",
        topic("Download and use a texture pack", "Open a game's Video settings, select This game, and open Texture packs. Refresh the GitHub catalogue, filter to the game's verified disc ID, then choose Download and use or Use installed pack. Only compatible published packs can be selected. An empty catalogue means no packs are available, not that every game's textures can be downloaded."),
        topic("Replacement format and texture folders", "Enable Texture replacements with a hardware renderer. This core uses SwanStation VRAM-write PNG replacements named vram-write- plus the 32-character content hash. Older psxe packs and other emulator naming schemes are not interchangeable. The resolved Texture folder shows where dump/ and replacements/ live. A blank Custom texture folder returns to the automatic per-game location."),
        topic("Dump and create replacement textures", "Enable Dump textures for a short hardware-rendered session and visit the scenes you want to capture. Edit the dumped PNGs while preserving their matching names, then place them in replacements/ and enable replacements. Dumping costs storage and performance and has a per-session limit. Turn it off when finished; higher internal resolution alone is not a replacement pack."),
    ),
    chapter("emulation", "Emulation and performance", "Boot, speed, frame skipping, rewind and runahead",
        topic("CPU mode and console region", "Use the normal cached/recompiler mode for ordinary play; the interpreter is a slower diagnostic comparison. Keep Region on Auto unless testing a particular compatibility issue. Forcing PAL/NTSC changes timing and is not a safe way to make every game faster. Relaunch after boot/core changes."),
        topic("Frame limit, speed and FPS cap", "For normal play, enable the frame limiter, use 100% emulation speed and avoid a conflicting FPS cap. The game's original PAL/NTSC cadence and its own animation rate can differ. Turning limits off is useful for a benchmark but can speed the whole game and audio. A cap cannot make a device render faster than it can."),
        topic("Fast-forward", "Choose its multiplier in Emulation and assign a shortcut if desired. Activate it from the quick menu or your hotkey. Unlimited requests maximum speed; it does not guarantee a particular multiplier. Use the Audio fast-forward mute/volume controls if accelerated sound is distracting."),
        topic("Frame skip", "Off presents each frame. Auto/fixed frame skipping reduces displayed frames to help when the device cannot keep up, but movement looks less smooth. Try lowering internal resolution or disabling costly shaders first. Frame skip is not a replacement for correctly matching audio/video timing."),
        topic("Rewind, buffer and precision", "Enable Rewind, choose a buffer duration and snapshot frequency, then use the assigned rewind control. Longer/finer history uses more memory; read the displayed memory estimate and cap. History begins accumulating only during play and can be cleared by state/disc/session changes. It is not a permanent save."),
        topic("Runahead", "Start at Off. If a game runs with performance headroom, test one frame of runahead to reduce input-to-image delay. More frames require extra emulation and state work every frame. Reduce or disable it for slowdown, audio issues or state-sensitive games. It cannot remove Bluetooth/speaker latency outside the emulator."),
        topic("Reading performance results", "Use the OSD speed percentage and frame-time stability as well as FPS. A game can animate at 30 FPS while the console runs at full speed. Device heat, drivers and CPU/GPU limits differ. Compare the same scene, renderer and settings rather than a BIOS animation against gameplay."),
    ),
    chapter("audio", "Audio", "Volume, delay, crackle, output and background sound",
        topic("Master volume, mute and stereo swap", "Adjust Master volume in Audio; Mute silences output without ending emulation. Swap channels reverses left and right. Avoid boosted gain if loud sounds distort, and compare headphones with device speakers before changing emulation timing."),
        topic("Audio buffer and backend", "A smaller buffer reduces queued-audio delay but is more sensitive to underruns; a larger buffer can smooth crackles at the cost of latency. Test one offered buffer size at a time and restart when required. Choose between the available output backends and confirm the result on your device; the requested backend may fall back if unavailable."),
        topic("Reverb and fast-forward audio", "Skip reverb changes the original sound's ambience; it is not an HD-audio effect. Fast-forward mute suppresses accelerated audio, while Fast-forward volume changes its level when unmuted. These do not change the master volume's purpose."),
        topic("Background audio", "Audio's background option governs sound while the app is not foregrounded. App settings' library/pause-menu music and sound effects are separate from the emulated game's audio. To isolate a crackle, disable menu music, return to the same scene and compare ordinary playback rather than fast-forward."),
    ),
    chapter("controls", "Controllers and input", "Button mapping, analog sticks, profiles, gyro and macros",
        topic("Bind and clear buttons", "Open Controls, choose the correct player/scope, select an action and press the physical controller button to bind it. Clear removes that binding. Bind D-pad actions separately from stick axes. If gameplay works but menu navigation does not, check menu/confirm behaviour and orientation before remapping every game button."),
        topic("Digital versus analog mode", "Analog mode at start changes the emulated controller the game sees. Older games may need Digital; enable Analog for games supporting DualShock sticks, or assign Analog (toggle) to switch. D-pad as left stick sends the D-pad into an analog-stick role and is a separate option. Leave Multitap off for games that do not support it."),
        topic("Stick direction and response", "Swap X/Y only for axes genuinely exchanged; Invert X/Y reverses the selected axis. Inner deadzone ignores small centre movement, outer deadzone reaches full input sooner, anti-deadzone adds a minimum output, sensitivity changes gain, acceleration changes response with movement, and response curve changes the feel across the range. Test left and right sticks independently."),
        topic("Controller profiles", "Use the profile selector to load an existing mapping. Save changes to the active profile or Save as to create a named copy, using the actions offered by that profile screen. Choose the intended player and Global/This game scope. Mapping profiles contain the button map, stick modes and stick bindings, not device-specific stick feel or rumble. Portable profiles live in inputprofiles/. Deleting a profile removes that preset; it should not be the normal way to save an edit."),
        topic("Rumble and haptics", "Enable rumble for the selected player and use its test control to verify the physical device. Strength changes vibration intensity, not controller sensitivity. Touch haptics are phone feedback for virtual presses and are separate from game-requested controller rumble."),
        topic("Gyro aiming and steering", "Select a gyro mode and target stick, then tune sensitivity, smoothing and axis inversion. Aim and steering are different mappings. If the device has no suitable sensor, the screen may show an unavailable or fallback state. Start with low sensitivity and test a single game before enabling it globally."),
        topic("Gestures and macros", "Enable gestures only if you want touch gestures mapped to actions; configure their sensitivity and double-tap tap/hold mode. A macro sends selected emulated buttons together. Choose its buttons, trigger and repeat frequency; Hold keeps them pressed while active. Avoid mapping a trigger that conflicts with an essential game/menu action."),
        topic("Players and Multitap", "Choose the player before editing a mapping. For games with supported Multitap play, enable the adapter and configure each available player. Games that do not understand a Multitap may fail to recognise a controller. Test a normal two-player setup before changing the adapter mode."),
    ),
    chapter("touch", "Touch controls and skins", "Position, size, profiles, shoulder hit areas and artwork",
        topic("Show controls and edit layout", "Enable On-screen controls, then open Edit touch layout. Select a virtual button to move or resize it, and use the editor's layout/profile save action when finished. Check portrait and landscape layouts separately. Hiding touch controls does not unbind a physical gamepad."),
        topic("Compact shoulder touch areas", "Controls → Compact shoulder touch areas limits L1/L2/R1/R2 interaction closer to the visible buttons, reducing the large surrounding hit regions. Enable it if shoulder zones interfere with the game area. Test each shoulder press and check its position/size in the touch-layout editor."),
        topic("Touch profiles and multi-touch", "Load the profile you intend to change, edit it, then save/update that profile; Save as creates a separate preset. Deleting is not required to keep edits. Multi-touch allows simultaneous virtual presses; test combinations such as direction plus a face button. Back up profiles you want to share before resetting them."),
        topic("Import and select skins", "Open Skins to import a folder or ZIP of ic_controller_*.png images (including compatible iOS-format skin packs), or browse the offered catalogue. Select the skin after import. Use the per-game option for an individual game's artwork. Skin images change the controls' appearance, not the PlayStation renderer or game textures. A skin needs the expected assets; a picture alone is not a complete control profile."),
        topic("Pause button visibility", "Use the touch/on-screen menu controls to show, hide or reveal the pause button as offered. Before hiding it, assign Menu / Pause or enable Android Back to open the menu. Otherwise a touch-only player may have no convenient way back to settings."),
    ),
    chapter("shortcuts", "Shortcuts and quick menu", "Hotkeys, button combinations, OSD and session actions",
        topic("Assign a hotkey", "Open Settings → Shortcuts. Select the action, then press and release one button, or hold two buttons together and release both. The combination works in either order. Use Clear to remove it or cancel capture before leaving. Avoid assigning Menu / Pause and Close to the same combination."),
        topic("Available shortcut actions", "The PS1 shortcut list provides Menu / Pause, Cheats, Swap Disc, Texture Dump, Fast-forward toggle, Rewind, Screenshot, Restart Game, Close Game and Quit App. Assign Cheats to reach the running game's cheat list, and Texture Dump to capture textures while visiting a scene. Save/Load State remain available through their menu buttons; do not assume an unlisted shortcut exists. No universal key combination is assumed: your configured mapping is the reference."),
        topic("Android Back and Close / Exit", "Enable Back opens menu to make Android's back button/gesture pause into the menu. Close ends the current game; Restart reboots it; Swap Game starts another title. For external frontend launches, the return-to-launcher toggle determines where the close/exit action returns. Save before any session-ending action."),
        topic("Performance overlay: Off, Minimal, Full, Custom", "In Quick menu → On-Screen, choose whether OSD changes apply to This game or All games, then choose a mode. Off is the fresh-install default. Minimal shows a small set; Full expands it; Custom exposes individual fields. A game's saved override wins until returned to Inherit/global. OSD mode is saved between launches."),
        topic("Custom OSD fields", "Choose FPS, emulation speed, CPU/GPU work, devices, frame times, internal resolution, renderer and host usage as needed. Unavailable hardware counters are not evidence of zero usage. Internal resolution is the frame size, not the phone's screen resolution. Use fewer fields if the overlay covers gameplay."),
        topic("Screenshots and menu layout", "Screenshot captures the game image without the touch overlay. Use the quick menu's categories for display, performance, controls and achievements. Where rearranging is offered, hold/drag or use the shown controller move mode and save it. These arrangements do not change controller bindings or game settings."),
    ),
    chapter("saves", "Memory cards and save states", "Import, slots, loading, backups and compatibility",
        topic("Two different types of save", "An in-game save is written to an emulated memory card through the game's own Save menu. A save state snapshots the running emulator at a moment in time. Importing a memory card does not import save states, and loading a state does not replace a reliable long-term card backup."),
        topic("Import a memory card into Slot 1 or Slot 2", "Close the game first. Open Memory Cards, choose the intended game/card target, then use the slot's import action and select a supported PS1 card. Verify both slot and target before confirming replacement. Importing successfully means the file was accepted; the game still needs a save for its matching release and must read the chosen slot. Many games use Slot 1."),
        topic("Use the imported in-game save", "Relaunch the matching game and choose its own Load/Continue option. Check Slot 1/2, the active game's mounted card path and the game's region/revision if it cannot see the save. A similarly named game from another region may use a different save identifier. Do not format/reset a card while diagnosing a missing save."),
        topic("Export, reset and protect cards", "Export each slot you want to keep before replacing, resetting or moving it. Reset creates/clears a card and can erase all saves on that card; read the confirmation. Cards hold multiple game saves and have limited capacity. Let the game's save operation finish before closing or powering off."),
        topic("Save State and Load State", "Launch a game, open the quick menu and use Save State to choose a slot. Load State restores a slot for the corresponding game/session format. Sidebar → Save States manages stored states outside gameplay. Keep an in-game memory-card save as well: state compatibility can change between cores or versions."),
        topic("Empty or incompatible state slots", "Check that you launched the same game/playlist identity, the correct app and the correct user-data folder. A separate test app has separate data. States from the retired engine or another emulator cannot be assumed compatible with SwanStation. Do not delete old states until you have made a replacement in-game save and tested it."),
    ),
    chapter("cheats", "Cheats and downloaded databases", "Find a game, enable codes and update without a new APK",
        topic("Find cheats for the running game", "Open Cheats from the game menu or its assigned shortcut. The database lookup uses the identified disc ID/region where available. Check the displayed target before selecting a different listing. Search narrows results as you type; browse the database for a missing entry, but do not substitute another region just because its title is similar."),
        topic("Enable a cheat", "Select the codes you want, then enable the master cheat switch for that game. Some codes require a new race, level or game session, or an activation button. Read each code's notes. Test one at a time, preferably with a backup save. A listed code is not a guarantee of compatibility with every game revision."),
        topic("Download cheats from GitHub", "Use Download cheats in the database/tools area while online. It refreshes the published cheat package without updating the APK. The catalogue can only supply codes that have been published; no result may mean no exact game/region entry exists. Keep your own imported files backed up."),
        topic("Paste, import and reload", "Use Paste for a supported PS1 code, or Import for a compatible cheat file. Give custom codes meaningful names, check the target game and reload when needed. GameShark/Action Replay-style names do not imply every code encoding is supported; unsupported entries cannot safely be applied. PS2 PNACH files are not PS1 cheat files."),
        topic("Cheats and achievements", "Disable achievement tracking when experimenting with cheats or modified memory. An already transmitted achievement cannot be recalled by turning tracking off later. For normal achievement play, remove cheats and start a clean session. Back up saves before trying item, unlock or progression codes."),
    ),
    chapter("achievements", "RetroAchievements", "Sign-in, API sync, library badges and achievement artwork",
        topic("Sign in and enable tracking", "Open RetroAchievements while connected to the internet and sign in. Enable RetroAchievements permits tracking; disabling it is useful for testing and preserves the stored login/library data. Re-enable before a fresh game launch to resume normal tracking. Do not share passwords or API keys in bug reports."),
        topic("Sync the scanned library", "Scan your game library first. In RetroAchievements → Library progress, use RetroAchievements control panel to visit the account website while signed in. Find Keys, copy the Web API key into the app's separate Web API key field, then run Sync library. Username/password sign-in does not fill that key. Manual sync reads/hashes images, so large libraries and Android document storage can take time."),
        topic("Matched games and missing hashes", "After syncing, open the RetroAchievements library list and select a matched game to view its achievements and artwork outside gameplay. Matched does not mean already played: a supported unplayed game can show 0/total. Unmatched, unreadable or unsupported images need checking separately; do not assume a title-only match proves the disc hash is supported."),
        topic("Library achievement badges", "Supported/synced games can show achievement availability/progress in list, grid and shelf views, including PS one styling. A badge uses cached progress and may need syncing after play. Achievement art needs network access on first retrieval. Games without a matched set should not acquire a badge merely because their title resembles a supported release."),
        topic("Hardcore support", "This SwanStation integration does not currently enable Hardcore mode. A frontend label or old stored preference is not proof that Hardcore validation is active. Use the supported tracking features; do not rely on this build for verified Hardcore awards."),
    ),
    chapter("appearance", "App appearance and interface", "Themes, music, scaling and launcher preferences",
        topic("Original ARMSX1 and PS one styles", "Open App → Interface style and select Original ARMSX1 or PS one. Original keeps the normal frontend style; PS one changes the library/menu shell and controls. Colour themes and wallpapers are separate preferences. These change the app interface, not the game's emulated console or textures."),
        topic("Colours, wallpaper and backgrounds", "Use Theme for the colour scheme, including system/Material You and custom colours where offered. OLED-base and background colour alter the backdrop. Choose/import a wallpaper or background style with its controls; simple/RGB backgrounds and opacity affect how artwork and panels appear. Switching back to Original style restores its presentation rather than converting the ROM."),
        topic("Library and pause music", "Enable each music source separately, choose a custom file or restore the default, and adjust its own volume. Menu sound effects can use short clips in a selected folder named for events such as nav, select, submenu, menu, back, toggle_on, toggle_off, reset, slider, sleep and wake. Use supported audio formats and keep effect clips short."),
        topic("Toolbar, search, recents and keyboard", "Choose top/bottom toolbar placement in App settings. Toggle the search field and Recently Played independently. Adjust cover size, tile opacity and grid names for readability. Enable System keyboard if you prefer Android's IME; the built-in keyboard remains available for controller-driven entry."),
        topic("Interface size and font size", "Settings → Interface changes UI size and text size, not the internal game resolution. Start with moderate values and check both orientations. Larger text can wrap into additional lines; use a smaller overall UI scale if controls no longer fit. The manual follows the app theme and text sizing."),
        topic("Boot logo, activity sharing and Home behaviour", "The boot-logo switch changes the app startup presentation. Recent-game/activity sharing belongs to the social features, not the public cheat database. Home-blocking changes navigation behaviour while the app is active and cannot replace Android system permissions. Use the option descriptions to decide whether these preferences suit your device."),
    ),
    chapter("companion", "Dual-screen CTR companion", "Race HUD and what is game-specific",
        topic("Enable the CTR companion", "Use the CTR companion controls for a supported Crash Team Racing game/device setup. The companion is game-specific, not a generic two-screen mode for all PS1 games. Its available setting governs whether the race HUD is moved away from gameplay. Confirm the game/region is supported before expecting live race data."),
        topic("Race HUD and non-race screens", "During a supported race the companion displays the map, item box, timer/laps/Wumpa information and eight racer positions/portraits while keeping gameplay on the other screen. Boot/menu companion screens are not a guarantee of a live map in every adventure area. Disable the companion to return to ordinary single-screen presentation if the game state is unsupported."),
    ),
    chapter("maintenance", "Updates, diagnostics and community", "Stable/nightly releases, logs and support",
        topic("Check for app updates", "Use App settings' updater/check action while online. Automatic checking and Include nightly are separate toggles. Stable and nightly are release channels, not graphics modes. Android only accepts an in-place update with the same package/signing certificate and a compatible version code; a different test app is not the same installation."),
        topic("Install an update without losing data", "Back up important memory cards, close the game, then install the matching signed APK over the existing app. Do not uninstall just to bypass an update/signature error: uninstalling can remove private saves. Verify the app name/package and source of the APK. Older disabled updater builds may need one manual update."),
        topic("Logging, quiet mode and log level", "Enable logging in Advanced for a diagnostic run and select an appropriate detail level. Quiet suppresses logging; the controls are related rather than independent ways to improve speed. Reproduce the problem once, then use App → Logs/diagnostic export. Review exported material for private paths or account details before sharing it."),
        topic("Read-only paths, cache and reset", "Advanced can show the generated settings-file path and launch defaults such as expansion ROM/default executable. A displayed path is not necessarily an editable selector. Clear cache removes cached material, which may require downloads again; it is not a fix for every missing save. Use the clearly labelled export/reset tools, never delete a whole user-data folder to reset one setting."),
        topic("Discord, friends, website and release notes", "The sidebar provides Discord/community, GitHub, website, News/release notes, Friends and About. External links open the relevant app/browser. Social sign-in/activity controls are separate from RetroAchievements. News describes changes; this offline manual describes usage. Downloads and online account features still need internet."),
    ),
    chapter("troubleshooting", "Troubleshooting", "Fast checks before resetting or deleting data",
        topic("Game missing or file inaccessible", "Refresh the library, check the active search/collection/hidden filters, confirm the folder permission and verify the file still exists. For CUE, grant the containing folder and inspect track filenames. A ROM on cloud storage may not be locally readable yet. Changing video settings cannot repair a missing file."),
        topic("Slowdown or stutter", "Return to 100% speed with the normal limiter. Disable runahead, heavy shaders and texture dumping, then try a lower internal resolution. Compare the same scene in another supported renderer and watch heat/frame-time readings. Restore settings one at a time; avoid globally resetting games that already work."),
        topic("Picture sideways, cropped or too large", "Check Launcher orientation, Gameplay orientation and Display rotation independently. Return overscan to None and compare the normal aspect ratio, stretch and integer-scaling settings. A dual-screen handheld's display orientation can differ from a phone's. Relaunch after a renderer/driver change."),
        topic("Audio delayed or crackling", "Test ordinary speed without fast-forward, verify full-speed emulation, then compare offered audio buffers/backends. Try low-volume speakers and wired headphones to separate speaker distortion from emulation problems. Bluetooth introduces its own delay. Describe whether the fault is only BIOS audio or also present in gameplay."),
        topic("Settings or controls seem not to save", "Verify Global/This game scope, the active control profile and any per-game override. Relaunch for startup-only settings. A separate test app has separate preferences. An import/reset may replace your chosen values, so keep a backup and test an ordinary edit before deleting profiles."),
        topic("No shader, texture pack, cheats or achievements", "Check the relevant enable/master switch and correct game ID/region. Shaders need a supported installed preset; textures need compatible replacement files and hardware rendering; cheats need codes for that release; achievements need sign-in/tracking and a recognised game hash. These catalogues do not guarantee coverage for every game."),
        topic("Report a reproducible bug", "Include the app version, device/Android version, game serial/region/file format, actual renderer, relevant per-game overrides and the shortest steps that reproduce it. Add a screenshot/video or diagnostic log if useful. Omit passwords, API keys, BIOS files and ROMs. Export saves before installing a diagnostic build."),
    ),
)

/** Every word narrows the results immediately; search is offline and never inspects user files. */
internal fun searchManual(query: String): List<ManualMatch> {
    val words = query.trim().split(Regex("\\s+")).filter(String::isNotBlank)
    if (words.isEmpty()) return emptyList()
    return MANUAL_CHAPTERS.flatMap { chapter ->
        chapter.topics.filter { topic ->
            val text = "${chapter.title} ${chapter.summary} ${topic.title} ${topic.body}"
            words.all { text.contains(it, ignoreCase = true) }
        }.map { ManualMatch(chapter, it) }
    }.sortedByDescending { it.topic.title.startsWith(query.trim(), ignoreCase = true) }
}
